/** Query contracts translated verbatim from the iOS PGA provider at 8f595b0. */
internal object PgaQueries {
    val documents: Map<String, String> = mapOf(
        "CourseStats" to "query CourseStats(\$tournamentId: ID!) {\n  courseStats(tournamentId: \$tournamentId) {\n    ...CourseStatsFragment\n  }\n}\n\nfragment CourseStatsFragment on TournamentHoleStats {\n  tournamentId\n  courses {\n    tournamentId\n    courseId\n    courseName\n    courseCode\n    holeDetailsAvailability\n    par\n    yardage\n    hostCourse\n    courseImage\n    roundHoleStats {\n      roundHeader\n      roundNum\n      live\n      enablePaceOfPlay\n      paceOfPlayLabelTitle\n      paceOfPlayDescription\n      paceOfPlayHeader\n      scoringHeader\n      holeStats {\n        ... on CourseHoleStats {\n          __typename\n          paceOfPlay {\n            ...PaceOfPlayFragment\n          }\n          averagePaceOfPlay\n          courseHoleNum\n          parValue\n          yards\n          scoringAverage\n          scoringAverageDiff\n          scoringDiffTendency\n          eagles\n          birdies\n          pars\n          bogeys\n          doubleBogey\n          rank\n          holeImage\n          live\n        }\n        ... on SummaryRow {\n          __typename\n          rowType\n          par\n          scoringAverageDiff\n          scoringDiffTendency\n          yardage\n          scoringAverage\n          eagles\n          birdies\n          pars\n          bogeys\n          doubleBogey\n          averagePaceOfPlay\n        }\n      }\n    }\n    courseOverview {\n      id\n      image\n      name\n      city\n      state\n      country\n    }\n  }\n}\n\nfragment PaceOfPlayFragment on CourseHoleStatsPaceData {\n  puttingRank\n  puttingTime\n  offTeeRank\n  offTeeTime\n  overallRank\n  overallTime\n  approachRank\n  approachTime\n  averageHoleRank\n  averageHoleTime\n}",
        "Coverage" to "query Coverage(\$tournamentId: ID!) {\n  coverage(tournamentId: \$tournamentId) {\n    id\n    tournamentName\n    countryCode\n    coverageType {\n      __typename\n      ... on BroadcastFullTelecast {\n        id\n        streamTitle\n        roundNumber\n        channelTitle\n        roundDisplay\n        startTime\n        endTime\n        liveStatus\n      }\n      ... on BroadcastFeaturedGroup {\n        id\n        streamTitle\n        roundNumber\n        channelTitle\n        roundDisplay\n        startTime\n        endTime\n        courseId\n        groups {\n          id\n          extendedCoverage\n          playerLastNames\n          liveStatus\n        }\n        liveStatus\n      }\n      ... on BroadcastFeaturedHole {\n        id\n        streamTitle\n        roundNumber\n        channelTitle\n        roundDisplay\n        startTime\n        endTime\n        courseId\n        featuredHoles\n        liveStatus\n      }\n    }\n  }\n}",
        "CurrentLeadersCompressed" to "query CurrentLeadersCompressed(\$tournamentId: ID!) {\n  currentLeadersCompressed(tournamentId: \$tournamentId) {\n    id\n    payload\n  }\n}",
        "Field" to "query Field(\$fieldId: ID!, \$includeWithdrawn: Boolean, \$changesOnly: Boolean) {\n  field(id: \$fieldId, includeWithdrawn: \$includeWithdrawn, changesOnly: \$changesOnly) {\n    tournamentName\n    id\n    lastUpdated\n    message\n    rangeAvailable\n    standingsHeader\n    features {\n      name\n      new\n      tooltipText\n      tooltipTitle\n      fieldStatType\n      leaderboardFeatures\n    }\n    players {\n      ...FieldPlayer\n      teammate {\n        id\n        firstName\n        lastName\n        shortName\n        displayName\n        amateur\n        country\n        countryFlag\n        qualifier\n        alternate\n        withdrawn\n        status\n        owgr\n        rankingPoints\n      }\n    }\n    alternates {\n      ...FieldPlayer\n    }\n  }\n}\n\nfragment FieldPlayer on PlayerField {\n  id\n  alphaSort\n  firstName\n  lastName\n  shortName\n  displayName\n  amateur\n  favorite\n  country\n  countryFlag\n  headshot\n  qualifier\n  alternate\n  withdrawn\n  status\n  owgr\n  rankingPoints\n  rankLogoLight\n  rankLogoDark\n}",
        "GroupLocations" to "query GroupLocations(\$tournamentId: ID!, \$round: Int!) {\n  groupLocations(tournamentId: \$tournamentId, round: \$round) {\n    tournamentId\n    courses {\n      ...GroupCourseFragment\n    }\n  }\n}\n\nfragment GroupCourseFragment on GroupLocationCourse {\n  tournamentAndCourseId\n  tournamentId\n  courseId\n  round\n  courseName\n  holes {\n    holeNumber\n    par\n    yardage\n    groups {\n      groupSort\n      groupNum\n      round\n      location\n      color\n      playerData {\n        addressingBall\n        nextToHit\n      }\n    }\n  }\n}",
        "HoleDetails" to "query HoleDetails(\$tournamentId: ID!, \$courseId: ID!, \$hole: Int!) {\n  holeDetails(tournamentId: \$tournamentId, courseId: \$courseId, hole: \$hole) {\n    id\n    tournamentId\n    statsAvailability\n    holeNum\n    courseId\n    holeImage\n    holeImageLandscape\n    tourcastURL\n    tourcastURLWeb\n    statsSummary {\n      tournamentId\n      courseId\n      holeNum\n      eagles\n      eaglesPercent\n      birdies\n      birdiesPercent\n      pars\n      parsPercent\n      bogeys\n      bogeysPercent\n      doubleBogeys\n      doubleBogeysPercent\n    }\n    holeInfo {\n      holeNum\n      par\n      yards\n      scoringAverageDiff\n      aboutThisHole\n      rank\n    }\n    rounds {\n      roundNum\n      groups {\n        groupNumber\n        groupLocation\n        groupLocationCode\n        tourcastURL\n        tourcastURLWeb\n        players {\n          playerId\n          firstName\n          lastName\n          countryFlag\n          headshot\n          position\n          total\n          roundScore\n          country\n        }\n      }\n    }\n  }\n}",
        "LeaderboardCompressedV3" to "query LeaderboardCompressedV3(\$leaderboardCompressedV3Id: ID!) {\n  leaderboardCompressedV3(id: \$leaderboardCompressedV3Id) {\n    id\n    payload\n  }\n}",
        "LeaderboardHoleByHole" to "query LeaderboardHoleByHole(\$tournamentId: ID!, \$round: Int) {\n  leaderboardHoleByHole(tournamentId: \$tournamentId, round: \$round) {\n    tournamentId\n    tournamentName\n    currentRound\n    holeHeaders {\n      holeNumber\n      hole\n      par\n    }\n    playerData {\n      playerId\n      out\n      in\n      total\n      courseId\n      courseCode\n      totalToPar\n      scores {\n        holeNumber\n        par\n        yardage\n        sequenceNumber\n        score\n        status\n        roundScore\n      }\n    }\n    courses {\n      id\n      courseName\n      courseCode\n      hostCourse\n      scoringLevel\n    }\n    rounds {\n      roundNumber\n      displayText\n    }\n  }\n}",
        "ScorecardCompressedV3" to "query ScorecardCompressedV3(\$tournamentId: ID!, \$playerId: ID!) {\n  scorecardCompressedV3(tournamentId: \$tournamentId, playerId: \$playerId) {\n    id\n    payload\n  }\n}",
        "shotDetailsV4Compressed" to "query shotDetailsV4Compressed(\$tournamentId: ID!, \$playerId: ID!, \$round: Int!, \$includeRadar: Boolean) {\n  shotDetailsV4Compressed(tournamentId: \$tournamentId, playerId: \$playerId, round: \$round, includeRadar: \$includeRadar) {\n    id\n    payload\n  }\n}",
        "StatDetails" to "query StatDetails(\$tourCode: TourCode!, \$statId: String!, \$year: Int, \$eventQuery: StatDetailEventQuery) {\n  statDetails(tourCode: \$tourCode, statId: \$statId, year: \$year, eventQuery: \$eventQuery) {\n    __typename\n    tourCode\n    year\n    displaySeason\n    statId\n    statType\n    tournamentPills {\n      tournamentId\n      displayName\n    }\n    yearPills {\n      year\n      displaySeason\n    }\n    statTitle\n    statDescription\n    tourAvg\n    lastProcessed\n    statHeaders\n    statCategories {\n      category\n      displayName\n      subCategories {\n        displayName\n        stats {\n          statId\n          statTitle\n        }\n      }\n    }\n    rows {\n      ... on StatDetailsPlayer {\n        __typename\n        playerId\n        playerName\n        country\n        countryFlag\n        rank\n        rankDiff\n        rankChangeTendency\n        stats {\n          statName\n          statValue\n          color\n        }\n      }\n      ... on StatDetailTourAvg {\n        __typename\n        displayName\n        value\n      }\n    }\n    sponsorLogo\n  }\n}",
        "TeeTimesCompressedV2" to "query TeeTimesCompressedV2(\$teeTimesCompressedV2Id: ID!) {\n  teeTimesCompressedV2(id: \$teeTimesCompressedV2Id) {\n    id\n    payload\n  }\n}",
        "TourCupSplit" to "query TourCupSplit(\$tourCode: TourCode!, \$id: String, \$year: Int, \$eventQuery: StatDetailEventQuery) {\n  tourCupSplit(tourCode: \$tourCode, id: \$id, year: \$year, eventQuery: \$eventQuery) {\n    ...TourCupSplitMeta\n    fixedHeaders\n    columnHeaders\n    rankingsHeader\n    rankEyebrow\n    pointsEyebrow\n    message\n    partner\n    partnerLink\n    projectedPlayers {\n      ...Player\n      ...InfoRow\n    }\n    officialPlayers {\n      ...Player\n      ...InfoRow\n    }\n    yearPills {\n      year\n      displaySeason\n    }\n    winner {\n      id\n      rank\n      firstName\n      lastName\n      displayName\n      shortName\n      countryFlag\n      country\n      earnings\n      totals {\n        label\n        value\n      }\n    }\n  }\n}\n\nfragment TourCupSplitMeta on TourCupSplit {\n  id\n  title\n  detailCopy\n  projectedTitle\n  projectedLive\n  season\n  description\n  logo\n  logoAsset {\n    imagePath\n    imageOrg\n  }\n  options\n  tournamentPills {\n    tournamentId\n    displayName\n  }\n}\n\nfragment Player on TourCupCombinedPlayer {\n  __typename\n  id\n  firstName\n  lastName\n  displayName\n  shortName\n  countryFlag\n  country\n  rankingData {\n    projected\n    official\n    event\n    movement\n    movementAmount\n    logo\n    logoDark\n  }\n  pointData {\n    projected\n    official\n    event\n    movement\n    movementAmount\n    logo\n    logoDark\n  }\n  projectedSort\n  officialSort\n  thisWeekRank\n  previousWeekRank\n  columnData\n  tourBound\n}\n\nfragment InfoRow on TourCupCombinedInfo {\n  logo\n  logoDark\n  text\n  sortValue\n  toolTip\n}",
        "Tournaments" to "query Tournaments(\$ids: [ID!]) {\n  tournaments(ids: \$ids) {\n    ...TournamentFragment\n  }\n}\n\nfragment TournamentFragment on Tournament {\n  id\n  tournamentName\n  tournamentLogo\n  tournamentLocation\n  tournamentStatus\n  roundStatusDisplay\n  roundDisplay\n  roundStatus\n  roundStatusColor\n  currentRound\n  timezone\n  pdfUrl\n  seasonYear\n  displayDate\n  country\n  state\n  city\n  scoredLevel\n  events {\n    id\n    eventName\n    leaderboardId\n  }\n  courses {\n    id\n    courseName\n    courseCode\n    hostCourse\n    scoringLevel\n  }\n  weather {\n    logo\n    logoDark\n    logoAccessibility\n    tempF\n    tempC\n    condition\n    windDirection\n    windSpeedMPH\n    windSpeedKPH\n    precipitation\n    humidity\n  }\n  ticketsURL\n  tournamentSiteURL\n  formatType\n  features\n  conductedByLabel\n  conductedByLink\n  beautyImage\n  hideRolexClock\n  hideSov\n  headshotBaseUrl\n  shouldSubscribe\n  ticketsEnabled\n  useTournamentSiteURL\n  tournamentCategoryInfo {\n    type\n    logoLight\n    logoDark\n    label\n  }\n}",
        "Weather" to "query Weather(\$tournamentId: ID!) {\n  weather(tournamentId: \$tournamentId) {\n    title\n    accessibilityText\n    hourly {\n      title\n      condition\n      windDirection\n      windSpeedKPH\n      windSpeedMPH\n      humidity\n      precipitation\n      temperature {\n        ... on StandardWeatherTemp {\n          __typename\n          tempC\n          tempF\n        }\n        ... on RangeWeatherTemp {\n          __typename\n          minTempC\n          minTempF\n          maxTempC\n          maxTempF\n        }\n      }\n    }\n    daily {\n      title\n      condition\n      windDirection\n      windSpeedKPH\n      windSpeedMPH\n      humidity\n      precipitation\n      temperature {\n        ... on StandardWeatherTemp {\n          __typename\n          tempC\n          tempF\n        }\n        ... on RangeWeatherTemp {\n          __typename\n          minTempC\n          minTempF\n          maxTempC\n          maxTempF\n        }\n      }\n    }\n  }\n}",
    )
}
